CustomField.formula:
IF( AND(Percentage_of_Completion__c =0, Estimated_Percentage__c = 0), NULL, IF( Percentage_of_Completion__c >= Estimated_Percentage__c, IMAGE("/img/samples/color_green.gif" ,"Green", 15, 300), IF( (Estimated_Percentage__c - Percentage_of_Completion__c) <= 0.05, IMAGE("/img/samples/color_yellow.gif" ,"Yellow", 15, 300),
IMAGE("/img/samples/color_red.gif", "Red", 15, 300)
)))
